namespace ghidra.app.plugin.core.function;





using docking.action;
using docking.widgets.dialogs;
using ghidra.app.context;
using ghidra.app.context;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.util;

class CreateArrayAction : ListingContextAction {

	private static readonly KeyStroke DEFAULT_KEY_STROKE =
		KeyStroke.getKeyStroke(KeyEvent.VK_OPEN_BRACKET, 0);
	private FunctionPlugin plugin;

	public CreateArrayAction(FunctionPlugin plugin) : base("Define Array", plugin.getName(), KeyBindingType.SHARED)
    {
		this.plugin = plugin;

		setPopupMenu(plugin.getDataActionMenuName(null));
		setHelpLocation(new HelpLocation(plugin.getName(), "DataType"));

		initKeyStroke(DEFAULT_KEY_STROKE);
	}

	private void initKeyStroke(KeyStroke keyStroke) {
		if (keyStroke == null) {
			return;
		}

		setKeyBindingData(new KeyBindingData(keyStroke));
	}

	private void setPopupMenu(string name) {
		setPopupMenuData(new MenuData(
			new string[] { FunctionPlugin.SET_DATA_TYPE_PULLRIGHT, "Array..." }, null, "Array"));
	}

	/* @Override */
	protected bool isEnabledForContext(ListingActionContext context) {
		if (context.hasSelection()) {
			return false;
		}
		ProgramLocation location = context.getLocation();
		if (plugin.isValidDataLocation(location)) {
			setPopupMenu(plugin.getDataActionMenuName(location));
			return true;
		}
		if (location is VariableLocation) {
			setPopupMenu(plugin.getDataActionMenuName(location));
			return true;
		}
		return false;
	}

	/* @Override */
	public void actionPerformed(ListingActionContext context) {

		ProgramLocation loc = context.getLocation();
		Function fun = plugin.getFunction(context);
		if (loc is FunctionSignatureFieldLocation) {
			DataType dt = fun.getReturnType();
			if (dt == VoidDataType.dataType) {
				dt = DataType.DEFAULT;
			}
			if (dt.getLength() < 1) {
				return;
			}
			int n = getNumElements(dt, int.MaxValue, 1);
			if (n == 0) {
				return;
			}
			Array array = new ArrayDataType(dt, n, dt.getLength());
			plugin.createData(array, context, true, false);
		}
		else if (loc is VariableLocation) {
			VariableLocation varLoc = (VariableLocation) loc;
			Variable var = varLoc.getVariable();
			if (var.isStackVariable()) {
				DataType dt = var.getDataType();
				if (dt.getLength() < 1) {
					return;
				}
				int availableLen = plugin.getMaxStackVariableSize(fun, var);
				if (availableLen <= 0) {
					availableLen = 1;
				}
				int maxElements = availableLen / var.getDataType().getAlignedLength();
				int n = getNumElements(dt, int.MaxValue, maxElements);
				if (n == 0) {
					return;
				}
				Array array = new ArrayDataType(dt, n, -1);
				plugin.createData(array, context, true, true);
			}
		}
	}

	/**
	 * Get the number of elements to create from the user.
	 */
	private int getNumElements(DataType dt, int maxElements, int initial) {
		NumberInputDialog dialog =
			new NumberInputDialog(dt.getDisplayName() + " Elements", initial, 1, maxElements);

		if (!dialog.show()) {
			return 0;  // cancelled
		}

		return dialog.getValue();
	}
}
